window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-76c72e11b8d65128"]={"versions": [{"id": "FIG-76c72e11b8d65128", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Aktivitätsdiagramm (Modellierung eines elementaren Algorithmus-Teilschritts).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Foundation / Classic & Adaptive Platform (<code>AUTOSAR_FO_PRS_E2EProtocol</code>). E2E-Bibliothek (End-to-End Communication Protection), spezialisiert auf Methoden-Profile (<code>PXXm</code>, z. B. P04m, P07m für RPC-/Service-Methoden im Kontext von SOME/IP und IPC).</li>\n<li><strong>Technischer Zweck:</strong> Normative Spezifikation des atomaren Verhaltensschritts „Increment Counter“ innerhalb der Schutz- und Weiterleitungsfunktionen zur deterministischen Generierung von Sequenznummern (Alive-Counter) zur Beherrschung von Übertragungsfehlern (Nachrichtenverlust, Wiederholung, Einfügung, falsche Reihenfolge gemäß ISO 26262 ASIL D / <code>RS_E2E_08539</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Funktionen / Funktionskontexte:</strong></li>\n<li><code>E2E_PXXmProtect()</code>: Schutzfunktion des Senders zur Berechnung und Serialisierung von E2E-Header-Feldern (Prüfsumme, Counter, Data ID, Length) in die Nutzdaten-PDU.</li>\n<li><code>E2E_PXXmForward()</code>: Gateway-/Brücken-Funktion zur Weiterleitung von Methoden-Nachrichten über Netzwerkgrenzen hinweg bei gleichzeitiger Fortschreibung des Übertragungsstatus.</li>\n<li>Platzhalter <code>”XX”</code>: Generischer Deskriptor für das konkrete E2E-Methodenprofil (z. B. <code>04</code>, <code>07</code>, <code>11</code>).</li>\n<li><strong>Datenstrukturen & Zustandselemente:</strong></li>\n<li><code>State</code>: In/Out-Zustandsstruktur der E2E-Instanz (z. B. <code>E2E_PXXmProtectStateType</code> bzw. <code>E2E_PXXmForwardStateType</code>).</li>\n<li><code>State-&gt;Counter</code>: Diskreter Zählerzustand (Alive Counter) mit definierter Bitbreite je nach Profil (typischerweise 4, 8 oder 16 Bit).</li>\n<li><strong>Kardinalitäten & Beziehungen:</strong></li>\n<li>Strikte 1:1-Zuordnung: Jede geschützte Methoden-Kommunikationsbeziehung erfordert eine dedizierte Instanz der <code>State</code>-Struktur im RAM des Aufrufers.</li>\n<li>Stereotypen: Keine Meta-Modell-Stereotypen («atpSplitable» etc.), da es sich um eine funktionale C-API-Ablaufspezifikation handelt.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Trigger & Ausführungskontext:</strong> Synchroner Aufruf innerhalb des linearen Ablaufs von <code>E2E_PXXmProtect()</code> bzw. <code>E2E_PXXmForward()</code>, üblicherweise nach Gültigkeitsprüfung der Eingangsdaten (<code>Config</code>, <code>State</code>, PDU-Puffer).</li>\n<li><strong>Ablaufschritte (UML-Kontrollfluss):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Initial Node:</strong> Eintritt in den Teilschritt „Increment Counter“.</li>\n<li><strong>Action (<code>State-&gt;Counter++</code>):</strong> Inkrementierung des aktuellen Zählerwerts um <code>1</code>.</li>\n<li><strong>Wrap-Around-Bedingung (UML-Note zu <code>PRS_E2E_01181</code>):</strong> Erreicht <code>Counter</code> das profildefinierte Maximum (<code>Counter_Max</code>), rollt der nächste Zählerwert zwingend auf <code>0</code> über (<code>(Counter + 1) % (Counter_Max + 1)</code>).</li>\n<li><strong>Activity Final Node:</strong> Verlassen des Teilschritts; Fortsetzung der E2E-Schutzsequenz (z. B. CRC-Berechnung über Payload und aktualisierten Header).</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Fehlerpfade & Synchronität:</strong> Rein deterministischer, synchroner In-Memory-Vorgang ohne Verzweigungen, asynchrone Callbacks oder Det-/Dem-Meldungen.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Zuordnung:</strong></li>\n<li><code>PRS_E2E_01180</code>: Verpflichtende Einhaltung des in Figur 6.33 definierten Ablaufs für alle E2E-Methodenprofile.</li>\n<li><code>PRS_E2E_01181</code> / <code>RS_E2E_08539</code>: Gewährleistung des definierten Modulo-Überlaufs auf 0 (Verbot von Saturation-Arithmetik).</li>\n<li><strong>Implementierungs- & Integrationshinweise:</strong></li>\n<li><strong>Typbreite vs. Bitbreite:</strong> Wenn der zugrundeliegende C-Datentyp größer ist als die Profil-Zählerbreite (z. B. <code>uint8</code> für einen 4-Bit-Zähler mit Wertebereich <code>0..14</code> oder <code>0..15</code>), muss die Implementierung nach dem Inkrement ein explizites Zurücksetzen bzw. Maskieren auf <code>0</code> erzwingen:</li>\n</ul>\n<p class=\"fig-p\">```c</p>\n<p class=\"fig-p\">State->Counter++;</p>\n<p class=\"fig-p\">if (State->Counter > PROFILE_COUNTER_MAX) {</p>\n<p class=\"fig-p\">State->Counter = 0;</p>\n<p class=\"fig-p\">}</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Reentrancy & Thread Safety:</strong> Die E2E-Bibliotheksfunktionen sind per AUTOSAR-Vorgabe „reentrant for different channels, non-reentrant for the same channel“. Das aufrufende BSW-Modul (z. B. RTE, SOME/IP-Transformer oder Gateway) muss sicherstellen, dass derselbe <code>State</code>-Pointer nicht nebenläufig ohne Mutex/Lock aufgerufen wird.</li>\n<li><strong>Initialisierung:</strong> Der Zähler beginnt nach Initialisierung via <code>E2E_PXXmProtectInit()</code> üblicherweise bei <code>0</code>. Der erste Aufruf von <code>E2E_PXXmProtect()</code> inkrementiert ihn entsprechend der profilspezifischen Platzierung des Teilschritts.</li>\n</ul>"}, {"id": "FIG-aef860a29a4ddd0d", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Aktivitätsdiagramm (Modellierung eines elementaren Algorithmus-Teilschritts).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Foundation / Classic & Adaptive Platform (<code>AUTOSAR_FO_PRS_E2EProtocol</code>). E2E-Bibliothek (End-to-End Communication Protection), spezialisiert auf Methoden-Profile (<code>PXXm</code>, z. B. P04m, P07m für RPC-/Service-Methoden im Kontext von SOME/IP und IPC).</li>\n<li><strong>Technischer Zweck:</strong> Normative Spezifikation des atomaren Verhaltensschritts „Increment Counter“ innerhalb der Schutz- und Weiterleitungsfunktionen zur deterministischen Generierung von Sequenznummern (Alive-Counter) zur Beherrschung von Übertragungsfehlern (Nachrichtenverlust, Wiederholung, Einfügung, falsche Reihenfolge gemäß ISO 26262 ASIL D / <code>RS_E2E_08539</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Funktionen / Funktionskontexte:</strong></li>\n<li><code>E2E_PXXmProtect()</code>: Schutzfunktion des Senders zur Berechnung und Serialisierung von E2E-Header-Feldern (Prüfsumme, Counter, Data ID, Length) in die Nutzdaten-PDU.</li>\n<li><code>E2E_PXXmForward()</code>: Gateway-/Brücken-Funktion zur Weiterleitung von Methoden-Nachrichten über Netzwerkgrenzen hinweg bei gleichzeitiger Fortschreibung des Übertragungsstatus.</li>\n<li>Platzhalter <code>”XX”</code>: Generischer Deskriptor für das konkrete E2E-Methodenprofil (z. B. <code>04</code>, <code>07</code>, <code>11</code>).</li>\n<li><strong>Datenstrukturen & Zustandselemente:</strong></li>\n<li><code>State</code>: In/Out-Zustandsstruktur der E2E-Instanz (z. B. <code>E2E_PXXmProtectStateType</code> bzw. <code>E2E_PXXmForwardStateType</code>).</li>\n<li><code>State-&gt;Counter</code>: Diskreter Zählerzustand (Alive Counter) mit definierter Bitbreite je nach Profil (typischerweise 4, 8 oder 16 Bit).</li>\n<li><strong>Kardinalitäten & Beziehungen:</strong></li>\n<li>Strikte 1:1-Zuordnung: Jede geschützte Methoden-Kommunikationsbeziehung erfordert eine dedizierte Instanz der <code>State</code>-Struktur im RAM des Aufrufers.</li>\n<li>Stereotypen: Keine Meta-Modell-Stereotypen («atpSplitable» etc.), da es sich um eine funktionale C-API-Ablaufspezifikation handelt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Trigger & Ausführungskontext:</strong> Synchroner Aufruf innerhalb des linearen Ablaufs von <code>E2E_PXXmProtect()</code> bzw. <code>E2E_PXXmForward()</code>, üblicherweise nach Gültigkeitsprüfung der Eingangsdaten (<code>Config</code>, <code>State</code>, PDU-Puffer).</li>\n<li><strong>Ablaufschritte (UML-Kontrollfluss):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Initial Node:</strong> Eintritt in den Teilschritt „Increment Counter“.</li>\n<li><strong>Action (<code>State-&gt;Counter++</code>):</strong> Inkrementierung des aktuellen Zählerwerts um <code>1</code>.</li>\n<li><strong>Wrap-Around-Bedingung (UML-Note zu <code>PRS_E2E_01181</code>):</strong> Erreicht <code>Counter</code> das profildefinierte Maximum (<code>Counter_Max</code>), rollt der nächste Zählerwert zwingend auf <code>0</code> über (<code>(Counter + 1) % (Counter_Max + 1)</code>).</li>\n<li><strong>Activity Final Node:</strong> Verlassen des Teilschritts; Fortsetzung der E2E-Schutzsequenz (z. B. CRC-Berechnung über Payload und aktualisierten Header).</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Fehlerpfade & Synchronität:</strong> Rein deterministischer, synchroner In-Memory-Vorgang ohne Verzweigungen, asynchrone Callbacks oder Det-/Dem-Meldungen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Zuordnung:</strong></li>\n<li><code>PRS_E2E_01180</code>: Verpflichtende Einhaltung des in Figur 6.33 definierten Ablaufs für alle E2E-Methodenprofile.</li>\n<li><code>PRS_E2E_01181</code> / <code>RS_E2E_08539</code>: Gewährleistung des definierten Modulo-Überlaufs auf 0 (Verbot von Saturation-Arithmetik).</li>\n<li><strong>Implementierungs- & Integrationshinweise:</strong></li>\n<li><strong>Typbreite vs. Bitbreite:</strong> Wenn der zugrundeliegende C-Datentyp größer ist als die Profil-Zählerbreite (z. B. <code>uint8</code> für einen 4-Bit-Zähler mit Wertebereich <code>0..14</code> oder <code>0..15</code>), muss die Implementierung nach dem Inkrement ein explizites Zurücksetzen bzw. Maskieren auf <code>0</code> erzwingen:</li>\n</ul>\n<p class=\"fig-p\">```c</p>\n<p class=\"fig-p\">State->Counter++;</p>\n<p class=\"fig-p\">if (State->Counter > PROFILE_COUNTER_MAX) {</p>\n<p class=\"fig-p\">State->Counter = 0;</p>\n<p class=\"fig-p\">}</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Reentrancy & Thread Safety:</strong> Die E2E-Bibliotheksfunktionen sind per AUTOSAR-Vorgabe „reentrant for different channels, non-reentrant for the same channel“. Das aufrufende BSW-Modul (z. B. RTE, SOME/IP-Transformer oder Gateway) muss sicherstellen, dass derselbe <code>State</code>-Pointer nicht nebenläufig ohne Mutex/Lock aufgerufen wird.</li>\n<li><strong>Initialisierung:</strong> Der Zähler beginnt nach Initialisierung via <code>E2E_PXXmProtectInit()</code> üblicherweise bei <code>0</code>. Der erste Aufruf von <code>E2E_PXXmProtect()</code> inkrementiert ihn entsprechend der profilspezifischen Platzierung des Teilschritts.</li>\n</ul>"}, {"id": "FIG-89ecdd447f0ff0ea", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Aktivitätsdiagramm (Modellierung eines elementaren Algorithmus-Teilschritts).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Foundation / Classic & Adaptive Platform (<code>AUTOSAR_FO_PRS_E2EProtocol</code>). E2E-Bibliothek (End-to-End Communication Protection), spezialisiert auf Methoden-Profile (<code>PXXm</code>, z. B. P04m, P07m für RPC-/Service-Methoden im Kontext von SOME/IP und IPC).</li>\n<li><strong>Technischer Zweck:</strong> Normative Spezifikation des atomaren Verhaltensschritts „Increment Counter“ innerhalb der Schutz- und Weiterleitungsfunktionen zur deterministischen Generierung von Sequenznummern (Alive-Counter) zur Beherrschung von Übertragungsfehlern (Nachrichtenverlust, Wiederholung, Einfügung, falsche Reihenfolge gemäß ISO 26262 ASIL D / <code>RS_E2E_08539</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Funktionen / Funktionskontexte:</strong></li>\n<li><code>E2E_PXXmProtect()</code>: Schutzfunktion des Senders zur Berechnung und Serialisierung von E2E-Header-Feldern (Prüfsumme, Counter, Data ID, Length) in die Nutzdaten-PDU.</li>\n<li><code>E2E_PXXmForward()</code>: Gateway-/Brücken-Funktion zur Weiterleitung von Methoden-Nachrichten über Netzwerkgrenzen hinweg bei gleichzeitiger Fortschreibung des Übertragungsstatus.</li>\n<li>Platzhalter <code>”XX”</code>: Generischer Deskriptor für das konkrete E2E-Methodenprofil (z. B. <code>04</code>, <code>07</code>, <code>11</code>).</li>\n<li><strong>Datenstrukturen & Zustandselemente:</strong></li>\n<li><code>State</code>: In/Out-Zustandsstruktur der E2E-Instanz (z. B. <code>E2E_PXXmProtectStateType</code> bzw. <code>E2E_PXXmForwardStateType</code>).</li>\n<li><code>State-&gt;Counter</code>: Diskreter Zählerzustand (Alive Counter) mit definierter Bitbreite je nach Profil (typischerweise 4, 8 oder 16 Bit).</li>\n<li><strong>Kardinalitäten & Beziehungen:</strong></li>\n<li>Strikte 1:1-Zuordnung: Jede geschützte Methoden-Kommunikationsbeziehung erfordert eine dedizierte Instanz der <code>State</code>-Struktur im RAM des Aufrufers.</li>\n<li>Stereotypen: Keine Meta-Modell-Stereotypen («atpSplitable» etc.), da es sich um eine funktionale C-API-Ablaufspezifikation handelt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Trigger & Ausführungskontext:</strong> Synchroner Aufruf innerhalb des linearen Ablaufs von <code>E2E_PXXmProtect()</code> bzw. <code>E2E_PXXmForward()</code>, üblicherweise nach Gültigkeitsprüfung der Eingangsdaten (<code>Config</code>, <code>State</code>, PDU-Puffer).</li>\n<li><strong>Ablaufschritte (UML-Kontrollfluss):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Initial Node:</strong> Eintritt in den Teilschritt „Increment Counter“.</li>\n<li><strong>Action (<code>State-&gt;Counter++</code>):</strong> Inkrementierung des aktuellen Zählerwerts um <code>1</code>.</li>\n<li><strong>Wrap-Around-Bedingung (UML-Note zu <code>PRS_E2E_01181</code>):</strong> Erreicht <code>Counter</code> das profildefinierte Maximum (<code>Counter_Max</code>), rollt der nächste Zählerwert zwingend auf <code>0</code> über (<code>(Counter + 1) % (Counter_Max + 1)</code>).</li>\n<li><strong>Activity Final Node:</strong> Verlassen des Teilschritts; Fortsetzung der E2E-Schutzsequenz (z. B. CRC-Berechnung über Payload und aktualisierten Header).</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Fehlerpfade & Synchronität:</strong> Rein deterministischer, synchroner In-Memory-Vorgang ohne Verzweigungen, asynchrone Callbacks oder Det-/Dem-Meldungen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Zuordnung:</strong></li>\n<li><code>PRS_E2E_01180</code>: Verpflichtende Einhaltung des in Figur 6.33 definierten Ablaufs für alle E2E-Methodenprofile.</li>\n<li><code>PRS_E2E_01181</code> / <code>RS_E2E_08539</code>: Gewährleistung des definierten Modulo-Überlaufs auf 0 (Verbot von Saturation-Arithmetik).</li>\n<li><strong>Implementierungs- & Integrationshinweise:</strong></li>\n<li><strong>Typbreite vs. Bitbreite:</strong> Wenn der zugrundeliegende C-Datentyp größer ist als die Profil-Zählerbreite (z. B. <code>uint8</code> für einen 4-Bit-Zähler mit Wertebereich <code>0..14</code> oder <code>0..15</code>), muss die Implementierung nach dem Inkrement ein explizites Zurücksetzen bzw. Maskieren auf <code>0</code> erzwingen:</li>\n</ul>\n<p class=\"fig-p\">```c</p>\n<p class=\"fig-p\">State->Counter++;</p>\n<p class=\"fig-p\">if (State->Counter > PROFILE_COUNTER_MAX) {</p>\n<p class=\"fig-p\">State->Counter = 0;</p>\n<p class=\"fig-p\">}</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Reentrancy & Thread Safety:</strong> Die E2E-Bibliotheksfunktionen sind per AUTOSAR-Vorgabe „reentrant for different channels, non-reentrant for the same channel“. Das aufrufende BSW-Modul (z. B. RTE, SOME/IP-Transformer oder Gateway) muss sicherstellen, dass derselbe <code>State</code>-Pointer nicht nebenläufig ohne Mutex/Lock aufgerufen wird.</li>\n<li><strong>Initialisierung:</strong> Der Zähler beginnt nach Initialisierung via <code>E2E_PXXmProtectInit()</code> üblicherweise bei <code>0</code>. Der erste Aufruf von <code>E2E_PXXmProtect()</code> inkrementiert ihn entsprechend der profilspezifischen Platzierung des Teilschritts.</li>\n</ul>"}], "trans": [{"from": "FIG-76c72e11b8d65128", "to": "FIG-aef860a29a4ddd0d", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Diagrammkopf / Dokumentenrand: Der am oberen Bildrand überstehende Textfetzen aus dem umgebenden Spezifikationsdokument („...mForward() shall behave as shown in Figure 6.33...“) wurde entfernt.</li>\n</ul>"}, {"from": "FIG-aef860a29a4ddd0d", "to": "FIG-89ecdd447f0ff0ea", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
